详细调用步骤解析1. 用户入口 - ResourcePackage// 用户代码var handle = package.LoadAssetAsync&lt;Texture2D&gt;(&quot;UITextures/Background&quot;);

2. ResourcePackage统一处理// ResourcePackage.cspublic AssetHandle LoadAssetAsync&lt;TObject&gt;(string location, uint priority = 0)&#123;    DebugCheckInitialize();    AssetInfo assetInfo = ConvertLocationToAssetInfo(location, typeof(TObject));    return LoadAssetInternal(assetInfo, false, priority);&#125;

3. ResourceManager创建Provider// ResourceManager.cspublic AssetHandle LoadAssetAsync(AssetInfo assetInfo, uint priority)&#123;    string providerGUID = nameof(LoadAssetAsync) + assetInfo.GUID;    ProviderOperation provider = TryGetAssetProvider(providerGUID);    if (provider == null)    &#123;        provider = new AssetProvider(this, providerGUID, assetInfo);        ProviderDic.Add(providerGUID, provider);        OperationSystem.StartOperation(PackageName, provider);    &#125;    return provider.CreateHandle&lt;AssetHandle&gt;();&#125;

4. AssetProvider执行加载// AssetProvider.csprotected override void ProcessBundleResult()&#123;    _loadAssetOp = BundleResultObject.LoadAssetAsync(MainAssetInfo);    // ... 处理加载结果    AssetObject = _loadAssetOp.Result;&#125;

场景加载特殊处理场景加载与普通资源加载有所不同，每次加载都会创建新的Provider：
// ResourceManager.cs Line 118-151public SceneHandle LoadSceneAsync(AssetInfo assetInfo, LoadSceneParameters loadSceneParams, bool suspendLoad, uint priority)&#123;    // 场景的ProviderGUID每次加载都会变化（支持同场景多次加载）    string providerGUID = $&quot;&#123;assetInfo.GUID&#125;-&#123;++_sceneCreateIndex&#125;&quot;;    ProviderOperation provider;    &#123;        provider = new SceneProvider(this, providerGUID, assetInfo, loadSceneParams, suspendLoad);        provider.InitProviderDebugInfo();        ProviderDic.Add(providerGUID, provider);        OperationSystem.StartOperation(PackageName, provider);    &#125;    provider.Priority = priority;    var handle = provider.CreateHandle&lt;SceneHandle&gt;();    handle.PackageName = PackageName;    SceneHandles.Add(handle);    return handle;&#125;

场景加载流程图flowchart TD    A[&quot;LoadSceneAsync&quot;] --&gt;|生成唯一GUID| B[&quot;创建SceneProvider&quot;]    B --&gt;|不复用Provider| C[&quot;每次都是新Provider&quot;]    C --&gt;|LoadSceneParameters| D[&quot;Unity SceneManager&quot;]    D --&gt;|支持暂停加载| E[&quot;suspendLoad=true&quot;]    D --&gt;|正常加载| F[&quot;suspendLoad=false&quot;]    E --&gt; G[&quot;加载到90%暂停&quot;]    F --&gt; H[&quot;完整加载场景&quot;]    G --&gt; I[&quot;用户调用ActivateScene&quot;]    H --&gt; J[&quot;SceneHandle返回&quot;]    I --&gt; J    %% 样式定义    style A fill:#ff6b6b,stroke:#ffffff,stroke-width:2px,color:#ffffff    style B fill:#4ecdc4,stroke:#ffffff,stroke-width:2px,color:#000000    style C fill:#45b7d1,stroke:#ffffff,stroke-width:2px,color:#ffffff    style D fill:#f9ca24,stroke:#ffffff,stroke-width:2px,color:#000000    style E fill:#6c5ce7,stroke:#ffffff,stroke-width:2px,color:#ffffff    style F fill:#a29bfe,stroke:#ffffff,stroke-width:2px,color:#ffffff    style G fill:#fd79a8,stroke:#ffffff,stroke-width:2px,color:#ffffff    style H fill:#00d2d3,stroke:#ffffff,stroke-width:2px,color:#ffffff    style I fill:#ff9ff3,stroke:#ffffff,stroke-width:2px,color:#000000    style J fill:#00aaff,stroke:#ffffff,stroke-width:2px,color:#ffffff

AssetInfo转换和查询机制Location到AssetInfo的转换// ResourcePackage.cs Line 1153-1160private AssetInfo ConvertLocationToAssetInfo(string location, System.Type assetType)&#123;    return _playModeImpl.ActiveManifest.ConvertLocationToAssetInfo(location, assetType);&#125;private AssetInfo ConvertAssetGUIDToAssetInfo(string assetGUID, System.Type assetType)&#123;    return _playModeImpl.ActiveManifest.ConvertAssetGUIDToAssetInfo(assetGUID, assetType);&#125;

AssetInfo包含的关键信息public class AssetInfo&#123;    public string AssetPath;        // 资源路径    public string GUID;            // 资源GUID    public System.Type AssetType;  // 资源类型    public PackageAsset Asset;     // 包资源信息    public ELoadMethod LoadMethod; // 加载方法    public bool IsInvalid;         // 是否无效    public string Error;           // 错误信息&#125;

资源回收和缓存机制资源回收策略YooAsset提供了多种资源回收方式：
1. 强制回收所有资源// ResourcePackage.cs Line 332-347public UnloadAllAssetsOperation UnloadAllAssetsAsync(UnloadAllAssetsOptions options)&#123;    DebugCheckInitialize();    var operation = new UnloadAllAssetsOperation(_resourceManager, options);    OperationSystem.StartOperation(PackageName, operation);    return operation;&#125;

2. 回收未使用的资源// ResourcePackage.cs Line 355-361public UnloadUnusedAssetsOperation UnloadUnusedAssetsAsync(int loopCount = 10)&#123;    DebugCheckInitialize();    var operation = new UnloadUnusedAssetsOperation(_resourceManager, loopCount);    OperationSystem.StartOperation(PackageName, operation);    return operation;&#125;

3. 尝试卸载指定资源// ResourcePackage.cs Line 367-382public void TryUnloadUnusedAsset(AssetInfo assetInfo, int loopCount = 10)&#123;    DebugCheckInitialize();    _resourceManager.TryUnloadUnusedAsset(assetInfo, loopCount);&#125;

资源回收机制详解ResourceManager中的回收逻辑：
// ResourceManager.cs Line 66-111public void TryUnloadUnusedAsset(AssetInfo assetInfo, int loopCount)&#123;    while (loopCount &gt; 0)    &#123;        loopCount--;        // 卸载主资源包加载器        string mainBundleName = _bundleQuery.GetMainBundleName(assetInfo.Asset.BundleID);        var mainLoader = TryGetBundleFileLoader(mainBundleName);        if (mainLoader != null)        &#123;            mainLoader.TryDestroyProviders();            if (mainLoader.CanDestroyLoader())            &#123;                mainLoader.DestroyLoader();                LoaderDic.Remove(mainBundleName);            &#125;        &#125;        // 卸载依赖资源包加载器        foreach (var dependID in assetInfo.Asset.DependBundleIDs)        &#123;            string dependBundleName = _bundleQuery.GetMainBundleName(dependID);            var dependLoader = TryGetBundleFileLoader(dependBundleName);            if (dependLoader != null)            &#123;                if (dependLoader.CanDestroyLoader())                &#123;                    dependLoader.DestroyLoader();                    LoaderDic.Remove(dependBundleName);                &#125;            &#125;        &#125;    &#125;&#125;

性能优化特性1. Provider复用机制ResourceManager 通过 ProviderGUID 实现Provider复用，避免重复加载：
string providerGUID = nameof(LoadAssetAsync) + assetInfo.GUID;ProviderOperation provider = TryGetAssetProvider(providerGUID);if (provider == null)&#123;    // 只有不存在时才创建新的Provider    provider = new AssetProvider(this, providerGUID, assetInfo);&#125;

2. Bundle加载并发控制// ResourceManager.csprivate int _bundleLoadingMaxConcurrency;   // 最大并发数public int BundleLoadingCounter = 0;        // 当前加载计数internal bool BundleLoadingIsBusy()&#123;    return BundleLoadingCounter &gt;= _bundleLoadingMaxConcurrency;&#125;

3. WebGL平台同步加载优化#if UNITY_WEBGLif (_resManager.WebGLForceSyncLoadAsset())    _loadAssetOp.WaitForAsyncComplete();#endif

4. 场景自动清理机制// ResourceManager.cs Line 369-387private void OnSceneUnloaded(Scene scene)&#123;    List&lt;SceneHandle&gt; removeList = new List&lt;SceneHandle&gt;();    foreach (var sceneHandle in SceneHandles)    &#123;        if (sceneHandle.IsValid &amp;&amp; sceneHandle.SceneObject == scene)        &#123;            sceneHandle.Release();            removeList.Add(sceneHandle);        &#125;    &#125;    foreach (var sceneHandle in removeList)    &#123;        SceneHandles.Remove(sceneHandle);    &#125;&#125;

错误处理和调试支持1. 初始化状态检查[Conditional(&quot;DEBUG&quot;)]private void DebugCheckInitialize(bool checkActiveManifest = true)&#123;    if (_initializeStatus == EOperationStatus.None)        throw new Exception(&quot;Package initialize not completed !&quot;);    else if (_initializeStatus == EOperationStatus.Failed)        throw new Exception($&quot;Package initialize failed ! &#123;_initializeError&#125;&quot;);    if (checkActiveManifest &amp;&amp; _playModeImpl.ActiveManifest == null)        throw new Exception(&quot;Can not found active package manifest !&quot;);&#125;

2. 资源类型有效性检查[Conditional(&quot;DEBUG&quot;)]private void DebugCheckAssetLoadType(System.Type type)&#123;    if (type == null) return;    if (typeof(UnityEngine.Behaviour).IsAssignableFrom(type))        throw new Exception($&quot;Load asset type is invalid : &#123;type.FullName&#125; !&quot;);    if (typeof(UnityEngine.Object).IsAssignableFrom(type) == false)        throw new Exception($&quot;Load asset type is invalid : &#123;type.FullName&#125; !&quot;);&#125;

3. 调试信息支持ResourceManager 提供了丰富的调试接口：
// ResourceManager.cs Line 390-433internal List&lt;DebugProviderInfo&gt; GetDebugProviderInfos()internal List&lt;DebugBundleInfo&gt; GetDebugBundleInfos()internal DebugPackageData GetDebugPackageData()

资源未下载时的按需下载机制YooAsset的一个重要特性是按需下载（On-Demand Download）机制。当用户加载资源时发现资源尚未下载到本地，系统会根据配置自动进行下载，整个过程对用户透明。
资源下载需求检查在资源加载前，可以通过以下接口检查资源是否需要下载：
// ResourcePackage.cs Line 390-410public bool IsNeedDownloadFromRemote(string location)&#123;    DebugCheckInitialize();    AssetInfo assetInfo = ConvertLocationToAssetInfo(location, null);    return IsNeedDownloadFromRemoteInternal(assetInfo);&#125;private bool IsNeedDownloadFromRemoteInternal(AssetInfo assetInfo)&#123;    if (assetInfo.IsInvalid)    &#123;        YooLogger.Warning(assetInfo.Error);        return false;    &#125;    // 检查主Bundle是否需要下载    BundleInfo bundleInfo = _bundleQuery.GetMainBundleInfo(assetInfo);    if (bundleInfo.IsNeedDownloadFromRemote())        return true;    // 检查依赖Bundle是否需要下载    List&lt;BundleInfo&gt; depends = _bundleQuery.GetDependBundleInfos(assetInfo);    foreach (var depend in depends)    &#123;        if (depend.IsNeedDownloadFromRemote())            return true;    &#125;    return false;&#125;

按需下载的核心逻辑当资源加载时发现文件不存在，DCFSLoadAssetBundleOperation会自动处理下载：
