总结YooAsset的资源加载系统采用了高度模块化的设计：

分层架构：ResourcePackage → ResourceManager → Provider → Handle 的清晰分层
类型安全：通过泛型和AssetInfo确保类型安全
按需下载：透明的按需下载机制，支持在线和离线模式
性能优化：Provider复用、并发控制、平台特定优化
错误处理：完善的验证和错误处理机制
调试支持：丰富的调试接口和状态监控
灵活配置：支持多种下载策略和配置模式

按需下载机制的核心特性：

透明性：用户调用加载接口时，系统自动检查并处理未下载资源
可配置性：通过DisableOnDemandDownload控制按需下载行为
状态监控：提供完整的下载进度和状态反馈
错误处理：详细的错误信息和失败处理机制
依赖处理：自动处理资源依赖的下载需求

这种设计既保证了高性能，又提供了良好的可维护性和扩展性，同时通过按需下载机制实现了在线和离线模式的完美结合，是一个优秀的资源管理系统实现。

Unity优化—代码篇—GC什么是GC在游戏运行的时候，数据主要存储在内存中，当游戏的数据在不需要的时候，存储当前数据的内存就可以被回收以再次使用。内存垃圾是指当前废弃数据所占用的内存，垃圾回收（GC）是指将废弃的内存重新回收再次使用的过程。
GC 触发时：

主线程会被暂停
标记并扫描所有托管堆上的对象
回收不再被引用的对象

GC触发条件自动触发条件
堆内存分配超过阈值（Incremental GC约增加1MB触发一次）
定期检查（Editor模式下更频繁）
系统内存压力过大

常见触发场景void Update() &#123;    text.text = &quot;Score: &quot; + score; // 每次拼接产生新字符串&#125;void ProcessItems(List&lt;Item&gt; items) &#123;    foreach (var item in items) &#123;        var temp = new List&lt;int&gt;(); // 每次迭代分配    &#125;&#125;void SetValue(int value) &#123;    PlayerPrefs.SetInt(&quot;key&quot;, value); // 实际上不会装箱，但要注意    int v = (int)GetValue(); // 拆箱操作&#125;object GetValue() =&gt; 42; // 装箱，产生堆分配

GC 操作带来的问题
GC操作会需要大量的时间来运行，如果堆内存上有大量的变量或者引用需要检查，则检查的操作会十分缓慢，这就会使得游戏运行缓慢。
GC 会带来堆内存碎片的问题。当一个内存单元从堆内存上分配出来，它的大小取决于它存储的变量的大小。当该内存被回收到堆内存上时，有可能会让堆内存分割成碎片化的单元。也就是说，堆内存总体可以使用的内存单元较大，但是单独的内存单元较小，在下次内存分配的时候不能找到合适大小的存储单元，这也会触发 GC 或 内存扩展操作

游戏性能优化方案1. 字符串游戏性能优化使用StringBuilder替代字符串拼接//  错误做法string result = &quot;&quot;;for (int i = 0; i &lt; 1000; i++) &#123;    result += i; // 每次循环创建新字符串&#125;//  正确做法var sb = new StringBuilder(1000); // 预分配容量for (int i = 0; i &lt; 1000; i++) &#123;    sb.Append(i);&#125;string result = sb.ToString();

缓存常用字符串//  将常用字符串声明为常量或静态字段private static readonly string[] SCORE_FORMATS = new string[] &#123;    &quot;Score: &#123;0&#125;&quot;,    &quot;Final Score: &#123;0&#125;&quot;,    &quot;Best Score: &#123;0&#125;&quot;&#125;;//  对于文本组件，只在内容变化时更新private int lastScore = -1;void UpdateScore(int score) &#123;    if (score != lastScore) &#123;        scoreText.text = string.Format(SCORE_FORMATS[0], score);        lastScore = score;    &#125;&#125;

2. 集合与数组游戏性能优化预分配集合容量//  未指定初始容量，多次扩容List&lt;Vector3&gt; positions = new List&lt;Vector3&gt;();for (int i = 0; i &lt; 1000; i++) &#123;    positions.Add(Vector3.zero); // 多次触发内部数组重新分配&#125;//  预分配足够容量List&lt;Vector3&gt; positions = new List&lt;Vector3&gt;(1000);

复用集合对象//  使用静态集合或对象池复用private static readonly List&lt;Vector3&gt; sharedList = new List&lt;Vector3&gt;();void GetPositions(List&lt;Vector3&gt; output) &#123;    output.Clear();    // 填充数据...&#125;// 调用GetPositions(sharedList);

使用数组替代List（已知容量时）//  固定大小使用数组private readonly Transform[] cachedTransforms;void Start() &#123;    cachedTransforms = new Transform[100];&#125;

3. 避免装箱拆箱使用泛型和非装箱API//  装箱产生堆分配ArrayList list = new ArrayList();list.Add(42); // int装箱为object//  使用泛型集合List&lt;int&gt; list = new List&lt;int&gt;();list.Add(42); // 无装箱

避免值类型作为接口类型使用//  结构体装箱struct Point &#123; public int X, Y; &#125;void Draw(object obj) &#123; &#125;Draw(new Point()); // 装箱//  使用泛型约束void Draw&lt;T&gt;(T obj) where T : struct &#123; &#125;Draw(new Point()); // 无装箱

4. 协程游戏性能优化避免在协程中频繁分配//  每次调用创建新迭代器IEnumerator RepeatAction() &#123;    while (true) &#123;        DoSomething();        yield return new WaitForSeconds(0.5f); // 每次创建新对象    &#125;&#125;//  缓存WaitForSeconds对象private WaitForSeconds waitHalfSecond = new WaitForSeconds(0.5f);IEnumerator RepeatAction() &#123;    while (true) &#123;        DoSomething();        yield return waitHalfSecond; // 复用对象    &#125;&#125;

使用WaitForEndOfFrame替代WaitForFixedUpdate//  对于UI更新，使用WaitForEndOfFrameIEnumerator UpdateUI() &#123;    yield return new WaitForEndOfFrame();    UpdateUIElements();&#125;

5. LINQ游戏性能优化避免在热路径使用LINQ//  LINQ产生闭包和委托分配var active = enemies.Where(e =&gt; e.isActive).ToList();var first = list.FirstOrDefault(e =&gt; e.id == targetId);//  使用传统循环var active = new List&lt;Enemy&gt;();foreach (var e in enemies) &#123;    if (e.isActive) active.Add(e);&#125;//  使用Find或手动查找Enemy found = null;foreach (var e in list) &#123;    if (e.id == targetId) &#123; found = e; break; &#125;&#125;

6. 闭包与委托游戏性能优化缓存常用委托//  每次创建新委托button.onClick.AddListener(() =&gt; OnClick());list.Sort((a, b) =&gt; a.value.CompareTo(b.value));//  预先定义委托private readonly System.Action clickHandler;void Start() &#123;    clickHandler = OnClick;    button.onClick.AddListener(clickHandler);&#125;//  或直接传递方法组button.onClick.AddListener(OnClick);

7. 对象池技术实现通用对象池//  简单对象池实现public class ObjectPool&lt;T&gt; where T : class, new()&#123;    private readonly Stack&lt;T&gt; pool = new Stack&lt;T&gt;();    private readonly System.Action&lt;T&gt; resetAction;    public ObjectPool(System.Action&lt;T&gt; resetAction = null, int initialSize = 10)    &#123;        this.resetAction = resetAction;        for (int i = 0; i &lt; initialSize; i++)            pool.Push(new T());    &#125;    public T Get()    &#123;        return pool.Count &gt; 0 ? pool.Pop() : new T();    &#125;    public void Return(T obj)    &#123;        resetAction?.Invoke(obj);        pool.Push(obj);    &#125;&#125;// 使用示例private readonly ObjectPool&lt;Bullet&gt; bulletPool = new ObjectPool&lt;Bullet&gt;(    resetAction: b =&gt; b.Reset(),    initialSize: 50);void FireBullet() &#123;    var bullet = bulletPool.Get(); // 从池中获取，无分配    // 使用子弹...&#125;void OnBulletDestroyed(Bullet bullet) &#123;    bulletPool.Return(bullet); // 归还到池中&#125;

8. Unity API游戏性能优化避免每帧获取组件//  每帧获取组件void Update() &#123;    var renderer = GetComponent&lt;Renderer&gt;();    renderer.material.color = Color.red;&#125;//  缓存组件引用private Renderer cachedRenderer;void Start() &#123;    cachedRenderer = GetComponent&lt;Renderer&gt;();&#125;void Update() &#123;    cachedRenderer.material.color = Color.red;&#125;

使用非分配API//  GetComponents返回新数组Component[] components = GetComponents&lt;Component&gt;();//  使用List版本复用列表private static readonly List&lt;Component&gt; componentCache = new List&lt;Component&gt;();GetComponents(componentCache);//  输入字符串获取键值string horizontal = Input.GetAxis(&quot;Horizontal&quot;);// 缓存输入轴名称或直接使用新输入系统// 新输入系统完全避免字符串分配

